      "replace": "    # Determine the log level to use first
    if log_type == 'result':
        log_level = 35  # RESULT level value
    elif log_type == 'debug':
        log_level = logging.DEBUG
    elif log_type == 'trace':
        # TRACE is lower than DEBUG
        log_level = logging.DEBUG - 5
    else:
        log_level = logging.INFO"
