  "test_path": "tests/test_add_trace_log_level.py",
  "test": "import io
import logging

from browser_use.logging_config import setup_logging

def test_trace_logging_outputs_message():
    stream = io.StringIO()
    # Force re‑setup so we get a fresh handler pointing at our stream
    logger = setup_logging(stream=stream, log_level='trace', force_setup=True)

    # Emit a TRACE message
    logging.getLogger('browser_use.test').trace('trace message for testing')

    # Retrieve stream contents
    output = stream.getvalue()
    # The output should contain our message and the TRACE level name
    assert 'TRACE' in output
    assert 'trace message for testing' in output"
}
